const ISLAMIC = ["Al-Ghazali","Ibn Rushd","Ibn Sina","Al-Farabi","Al-Kindi","Ibn Khaldun",
  "Al-Shatibi","Ibn Miskawayh","Mulla Sadra","Shah Waliullah","Suhrawardi","Ibn Hazm","Ibn Taymiyyah"];

const FONT_D = "'Cormorant Garamond','Iowan Old Style',Georgia,serif";
const FONT_B = "'Literata','Iowan Old Style',Georgia,'Times New Roman',serif";

const Card = ({ bg="#111", border="#222", borderLeft, children, style={} }) => (
  <div style={{ background:bg, border:`1px solid ${border}`, borderLeft, borderRadius:"10px",
    padding:"20px 22px", marginBottom:"16px", ...style }}>
    {children}
  </div>
);

const Expandable = ({ id, eKey, setEKey, header, headerColor="#d4a843", activeBg="#151005", activeBorder="#d4a84355", children }) => {
  const open = eKey===id;
  const toggle = () => setEKey(open?null:id);
  return (
    <div role="button" tabIndex={0} aria-expanded={open} onClick={toggle}
      onKeyDown={e=>{ if(e.key==="Enter"||e.key===" "){ e.preventDefault(); toggle(); } }}
      style={{
      marginBottom:"10px", padding:"15px 18px", cursor:"pointer", transition:"background .25s, border-color .25s",
      background: open ? activeBg : "#0f0f10",
      border:`1px solid ${open ? activeBorder : "#242424"}`, borderRadius:"10px",
    }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
        <div style={{ fontSize:"14px", color:headerColor, paddingRight:"12px", flex:1, lineHeight:"1.55", fontFamily:FONT_B }}>{header}</div>
        <div style={{ color:"#6a665a", fontSize:"11px", flexShrink:0, marginTop:"3px",
          transform: open ? "rotate(180deg)" : "none", transition:"transform .25s" }}>▼</div>
      </div>
      {open && <div className="reveal" style={{ marginTop:"12px", borderTop:"1px solid #2a2a2a", paddingTop:"12px" }}>{children}</div>}
    </div>
  );
};

const Analogies = ({ analogies, color }) => (
  <div>
    {analogies.map((a,i) => (
      <div key={i} style={{ background:"#0d0d0e",
        border:`1px solid ${color}22`, borderLeft:`2px solid ${color}`, borderRadius:"0 10px 10px 0",
        padding:"18px 20px", marginBottom:"14px" }}>
        <div style={{ fontFamily:FONT_D, fontSize:"21px", color, marginBottom:"8px" }}>
          {i+1}. {a.title}
        </div>
        <div style={{ fontFamily:FONT_B, fontSize:"15px", color:"#a39b8b", lineHeight:"1.85" }}>{a.text}</div>
      </div>
    ))}
  </div>
);

const SectionHeader = ({ color, pre, title, sub }) => (
  <div style={{ margin:"6px 0 26px" }}>
    {pre && <div style={{ fontSize:"11.5px", fontStyle:"italic", letterSpacing:"0.3px", color, opacity:0.9, marginBottom:"10px", lineHeight:1.5 }}>{pre}</div>}
    <h2 style={{ margin:0, fontFamily:FONT_D, fontSize:"clamp(30px,6vw,44px)", fontWeight:400, lineHeight:1.1, color:"#efe8d8" }}>{title}</h2>
    <div style={{ width:"44px", height:"2px", background:color, margin:"16px 0 12px", opacity:0.8 }} />
    {sub && <p style={{ margin:0, fontFamily:FONT_B, fontSize:"14px", fontStyle:"italic", color:"#8a8474", lineHeight:1.7 }}>{sub}</p>}
  </div>
);

const TabIntro = ({ text, color }) => (
  <Card bg="#0c0c0d" border={`${color}2a`} borderLeft={`2px solid ${color}`}
    style={{ fontFamily:FONT_B, fontSize:"14px", color:"#a39b8b", lineHeight:"1.85", marginBottom:"18px" }}>
    <div style={{ fontFamily:FONT_D, fontSize:"17px", fontStyle:"italic", color, marginBottom:"6px" }}>
      What you're about to read
    </div>
    {text}
  </Card>
);

const Genealogy = ({ text, color }) => (
  <Card bg="#0c0c0d" border="#222" borderLeft={`2px solid ${color}66`} style={{ marginTop:"22px" }}>
    <div style={{ fontFamily:FONT_D, fontSize:"21px", color, marginBottom:"8px" }}>Intellectual genealogy</div>
    <div style={{ fontFamily:FONT_B, fontSize:"14.5px", color:"#938d7c", lineHeight:"1.9" }}>{text}</div>
  </Card>
);

const Intersections = ({ items, color }) => (
  <div style={{ marginTop:"26px" }}>
    <div style={{ fontFamily:FONT_D, fontSize:"23px", color:"#b8b09c", marginBottom:"14px" }}>
      Intersections with other sections
    </div>
    {items.map((item,i) => (
      <Card key={i} bg="#0d0d0e" border="#222" borderLeft={`2px solid ${color}66`}>
        <div style={{ fontFamily:FONT_D, fontSize:"19px", color, marginBottom:"8px" }}>↔ {item.with}</div>
        <div style={{ fontFamily:FONT_B, fontSize:"14.5px", color:"#a29a7c", lineHeight:"1.85" }}>{item.text}</div>
      </Card>
    ))}
  </div>
);

// JumpNav: sticky in-page anchors that smooth-scroll within a tab's continuous body.
const JumpNav = ({ tabs, color }) => {
  const go = id => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior:"smooth", block:"start" });
  };
  const shorten = lbl => {
    let s = lbl.replace(/^Start Here:\s*/i, "");
    if (s.length > 30) s = s.slice(0, 28).trimEnd() + "…";
    return s;
  };
  return (
    <div className="jump" style={{ "--c":color }}>
      {tabs.map(([id,lbl]) => (
        <button key={id} onClick={()=>go(id)}>{shorten(lbl)}</button>
      ))}
    </div>
  );
};

// StackedSections: shared continuous-reading renderer for the common data shape.
const StackedSections = ({ data, pre, preface, prefaceLabel, bodyFont="16.5px", bodyColor="#d9d2c2", readMap, markRead }) => {
  const { color, bg, title, subtitle, epigraph, intro, sections, genealogy, intersections, analogies } = data;
  const tabId = TABID_BY_DATA.get(data) || "unknown";
  const observerRef = useRef(null);
  useEffect(() => {
    if (!markRead) return;
    observerRef.current = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const sid = entry.target.getAttribute("data-section-id");
          if (sid) markRead(tabId, sid);
        }
      });
    }, { threshold: 0.35 });
    return () => { if (observerRef.current) observerRef.current.disconnect(); };
  }, [tabId]);
  const sectionRef = (el) => { if (el && observerRef.current) observerRef.current.observe(el); };
  const jumpTabs = [
    ...sections.map(s => [s.id, s.label]),
    ...(genealogy ? [["gen","Genealogy"]] : []),
    ...(intersections ? [["cross","Intersections"]] : []),
    ...(analogies ? [["anal","Analogies"]] : []),
  ];
  return (
    <div>
      <SectionHeader color={color} pre={pre} title={title} sub={subtitle} />
      {intro && <TabIntro color={color} text={intro} />}
      {epigraph && (
        <Card bg="#0f0f10" border="#252525" style={{ fontFamily:FONT_B, color:"#a89a66", fontSize:"14.5px", fontStyle:"italic", lineHeight:1.8, marginBottom:"18px" }}>
          {epigraph}
        </Card>
      )}
      {preface && (
        <Card bg="#0e0c06" border={`${color}44`} borderLeft={`2px solid ${color}`}
          style={{ fontFamily:FONT_B, fontSize:"14.5px", color:"#c8b880", lineHeight:"1.9", marginBottom:"18px" }}>
          {prefaceLabel && (
            <div style={{ fontFamily:FONT_D, fontSize:"17px", fontStyle:"italic", color, marginBottom:"8px" }}>{prefaceLabel}</div>
          )}
          {preface}
        </Card>
      )}
      <JumpNav tabs={jumpTabs} color={color} />
      {sections.map((s,i) => {
        const isRead = readMap && readMap[`${tabId}::${s.id}`];
        return (
        <section key={s.id} id={s.id} data-section-id={s.id} ref={sectionRef} style={{ margin:"0 0 34px", scrollMarginTop:"64px" }}>
          <h3 style={{ margin:"0 0 12px", display:"flex", alignItems:"baseline", gap:"12px",
            fontFamily:FONT_D, fontWeight:500, fontSize:"clamp(21px,4.4vw,26px)", lineHeight:1.25, color:"#eee6d4" }}>
            <span style={{ color, fontSize:"15px", fontWeight:400, opacity:0.9, flexShrink:0 }}>{i+1}</span>
            <span>{s.label}</span>
            {isRead && <span title="Read" style={{ color:"#7fbf7f", fontSize:"13px", marginLeft:"auto" }}>✓</span>}
          </h3>
          <Card bg={bg} border={`${color}2a`} borderLeft={`2px solid ${color}`}
            style={{ fontFamily:FONT_B, lineHeight:"1.95", fontSize:bodyFont, color:bodyColor, whiteSpace:"pre-line", marginBottom:0 }}>
            {s.body}
          </Card>
        </section>
      );})}
      {genealogy && <div id="gen"><Genealogy text={genealogy} color={color} /></div>}
      {intersections && <div id="cross"><Intersections items={intersections} color={color} /></div>}
      {analogies && <div id="anal"><Analogies analogies={analogies} color={color} /></div>}
    </div>
  );
};

